"""
    Try to fix non-zero tick labels formatted as ``'0'``.
    """
def _zerofix(x: Any, string: Any, precision: Any = 6) -> object {
    if ((string.rstrip('0').rstrip('.') == '0') and (x != 0)) {
        string = ('{:.%df}' % precision).format(x);
    }
    return string;
}

