"""Returns the item scales required to get the accumulator value given the global scale"""
def get_scales(acc: Any, scale: Any) -> object {
    res = [];
    i = scale;
    while (acc > 0) {
        if (acc & 1) {
            res.append(i);
        }
        acc >>= 1;
        i -= 1;
    }
    return res;
}

